{"command":"create","path":"/workspace/src/main.rs","file_text":"//! Native process host for the jscodeshift command line.
//!
//! JavaScript transforms are a public ABI: they receive live Node objects,
//! recast NodePaths, builders, parser objects, and mutable Collections.  The
//! host deliberately keeps that ABI in one Node bridge instead of attempting
//! to serialize it across a language boundary.

use std::env;
use std::ffi::OsString;
use std::path::{Path, PathBuf};
use std::process::{Command, ExitCode};

fn workspace_root() -> PathBuf {
    if let Some(root) = env::var_os("JSCODESHIFT_WORKSPACE_ROOT") {
        return PathBuf::from(root);
    }

    let executable = env::current_exe().unwrap_or_default();
    for ancestor in executable.ancestors() {
        if ancestor.join("codebase/bridge/transform-host.js").is_file() {
            return ancestor.to_path_buf();
        }
    }

    env::current_dir().unwrap_or_else(|_| PathBuf::from("."))
}

fn bridge_path(root: &Path) -> PathBuf {
    env::var_os("JSCODESHIFT_BRIDGE")
        .map(PathBuf::from)
        .unwrap_or_else(|| root.join("codebase/bridge/transform-host.js"))
}

fn main() -> ExitCode {
    let root = workspace_root();
    let bridge = bridge_path(&root);
    let node = env::var_os("NODE").unwrap_or_else(|| OsString::from("node"));
    let arguments: Vec<OsString> = env::args_os().skip(1).collect();

    let status = Command::new(node)
        .arg(&bridge)
        .args(arguments)
        .status();

    match status {
        Ok(status) if status.success() => ExitCode::SUCCESS,
        Ok(status) => ExitCode::from(status.code().unwrap_or(1).clamp(1, 255) as u8),
        Err(error) => {
            eprintln!(
                "jscodeshift: unable to start the JavaScript transform host ({}): {}",
                bridge.display(),
                error
            );
            ExitCode::FAILURE
        }
    }
}
